INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT159-S3-Q22$batch11$, 159, 3, 22, $batch11$Must Be True$batch11$, $batch11$For a zoo to make a valuable contribution to the community, it must be well run. All large zoos that are well run have some full-time veterinarians on staff, but many small zoos that are well run have only part-time veterinarians. In addition, there are many large zoos that make valuable contributions to their communities and are open all year, while most small zoos are closed in winter.$batch11$, $batch11$If the statements above are true, then which one of the following must also be true?$batch11$, $batch11$D$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q22$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$Most large zoos are well run.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$No large, well-run zoos have any part-time veterinarians on staff.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$Some zoos that make valuable contributions to their communities have only part-time veterinarians on staff.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$Some zoos that are open all year have full-time veterinarians on staff.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$Most small zoos make valuable contributions to their communities.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Valuable contribution → well run. Large and well run → some full-time vets. Many large zoos make valuable contributions and are open all year.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Take those large zoos that contribute and are open all year. Contributing → well run. Large and well run → full-time vets. So those year-round zoos have full-time vets.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Some zoos open all year have full-time vets.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT159-S3-Q22$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$"Many" large zoos contribute, so many are well run. "Many" isn't "most."$batch11$), ($batch11$B$batch11$, $batch11$Large, well-run zoos have some full-time vets. They could have part-time vets too.$batch11$), ($batch11$C$batch11$, $batch11$Small zoos with only part-time vets are well run, but being well run doesn't mean they contribute.$batch11$), ($batch11$D$batch11$, $batch11$Many large zoos contribute and are open all year. Contributing makes them well run, and large well-run zoos have full-time vets.$batch11$), ($batch11$E$batch11$, $batch11$Well run is required to contribute, not enough. We know nothing about how many small zoos contribute.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT159-S3-Q22$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
